sparql_tries.sparql:
SELECT DISTINCT ?modelYear WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "26V430000" ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?modelYear .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?modelYear

SELECT DISTINCT ?componentName WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "10V388000" ;
            rc:affectsComponent ?component .
  ?component rc:name ?componentName .
}
ORDER BY ?componentName

SELECT DISTINCT ?campaignNumber ?initiatedBy WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber ;
          rc:initiatedBy ?initiatedBy .
  FILTER(REGEX(STR(?initiatedBy), "OVSC", "i"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?make a rc:Make ; rc:name "HYUNDAI" .
  ?model a rc:VehicleModel ; rc:ofMake ?make ; rc:name "PALISADE" .
  ?variant rc:ofModel ?model .
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant ;
            rc:campaignNumber ?campaignNumber ;
            rc:reportReceivedDate ?date .
  FILTER(YEAR(?date) = 2024)
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?modelName ?makeName WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?component ;
            rc:affects ?variant .
  ?component rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
ORDER BY ?makeName ?modelName

SELECT ?componentName (COUNT(DISTINCT ?campaign) AS ?campaignCount) WHERE {
  ?comp a rc:Component ; rc:name ?componentName .
  FILTER NOT EXISTS { ?child skos:broader ?comp }
  ?campaign rc:affectsComponent ?comp .
  FILTER EXISTS { ?c1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" }
  FILTER EXISTS { ?c2 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" }
}
GROUP BY ?componentName
ORDER BY DESC(?campaignCount)
LIMIT 1

SELECT ?campaignNumber (COUNT(DISTINCT ?makeName) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?model rc:name "SANTA FE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER(STR(?year) = "2021")
  OPTIONAL { ?campaign rc:reportReceivedDate ?date }
}
ORDER BY DESC(?date) ?campaignNumber

SELECT ?modelName (COUNT(DISTINCT ?campaign) AS ?campaignCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName .
}
GROUP BY ?modelName
ORDER BY DESC(?campaignCount)
LIMIT 1

SELECT (COUNT(DISTINCT ?campaign) AS ?count) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:reportReceivedDate ?date ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?date) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?comp ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  ?top a rc:Component ; rc:name ?topName .
  FILTER NOT EXISTS { ?top skos:broader ?parent . }
}
GROUP BY ?topName
ORDER BY DESC(?modelCount)
LIMIT 1

SELECT ?campaignNumber ?potentiallyAffected WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:parkOutside true ;
            rc:campaignNumber ?campaignNumber ;
            rc:potentiallyAffected ?potentiallyAffected .
}
ORDER BY DESC(?potentiallyAffected)
LIMIT 1

SELECT ?topName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v ;
     rc:affectsComponent ?comp .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name "GENESIS" .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT ?year (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects/rc:ofModel/rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?count)

SELECT DISTINCT ?campaignNumber ?defect WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:defectSummary ?defect . }
  OPTIONAL { ?r rc:consequenceSummary ?consequence . }
  OPTIONAL { ?r rc:affectsComponent ?c . ?c rc:name ?compName . }
  BIND(LCASE(CONCAT(COALESCE(?defect, ""), " ", COALESCE(?consequence, ""), " ", COALESCE(?compName, ""))) AS ?txt)
  FILTER(CONTAINS(?txt, "hydrogen"))
  FILTER(CONTAINS(?txt, "leak") || CONTAINS(?txt, "detect"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?manufacturer ?date WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:filedBy ?m . ?m rc:name ?manufacturer . }
  OPTIONAL { ?r rc:reportReceivedDate ?date . }
  OPTIONAL { ?r rc:defectSummary ?defect . }
  OPTIONAL { ?r rc:affectsComponent ?c . ?c rc:name ?compName . }
  FILTER (
    REGEX(STR(?defect), "integrated charging control unit|\\bICCU\\b", "i") ||
    REGEX(STR(?compName), "integrated charging control unit|\\bICCU\\b", "i")
  )
} ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defectSummary ?rootCause WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:defectSummary ?defectSummary }
  OPTIONAL { ?r rc:rootCause ?rootCause }
  BIND(CONCAT(COALESCE(?defectSummary, ""), " ", COALESCE(?rootCause, "")) AS ?text)
  FILTER(
    ( REGEX(?text, "trailer|\\btow(ing)?\\b|hitch", "i")
      || EXISTS { ?r rc:affectsComponent ?c . ?c rc:name ?cn . FILTER(CONTAINS(UCASE(?cn), "TRAILER")) } )
    && REGEX(?text, "water|moisture|liquid", "i")
    && REGEX(?text, "module|control unit|\\bECU\\b", "i")
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defectSummary WHERE {
  ?recall a rc:RecallCampaign ;
          rc:campaignNumber ?campaignNumber ;
          rc:defectSummary ?defectSummary .
  FILTER(REGEX(?defectSummary, "connecting rod bearing", "i") && REGEX(?defectSummary, "wear", "i"))
}
ORDER BY ?campaignNumber
